$('about').onclick=()=>$('aboutDialog').showModal();$('closeAbout').onclick=()=>$('aboutDialog').close();
document.querySelector('.panel-toggle').onclick=e=>{const button=e.currentTarget,open=document.querySelector('.panel').classList.toggle('open');button.setAttribute('aria-expanded',String(open));button.querySelector('span').textContent=open?'접기':'열기'};
document.addEventListener('keydown',e=>{if(['BUTTON','INPUT'].includes(document.activeElement?.tagName)||$('aboutDialog').open)return;if(e.code==='Space'){e.preventDefault();horn()}});updateUI();
